import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';

export function sendJson(ws: WebSocket, message: OutgoingMessage): void {
  ws.send(JSON.stringify(message));
}

export function sendUpsert(ws: WebSocket, index: number, entry: SessionEntry): void {
  sendJson(ws, {type: 'entry_upsert', index, entry});
}

export function sendDelta(ws: WebSocket, index: number, delta: string): void {
  sendJson(ws, {type: 'entry_delta', index, delta});
}

export function sendCommit(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_commit', index});
}

export function sendError(ws: WebSocket, code: string, message: string): void {
  sendJson(ws, {type: 'error', code, message});
}

export function sendSkip(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_skip', index});
}

export function sendStreamEnd(ws: WebSocket): void {
  sendJson(ws, {type: 'stream_end'});
}
export interface UserEntry {
  role: 'user';
  content: string;
  timestamp: string;
}

export interface AssistantEntry {
  role: 'assistant';
  content: string;
  timestamp: string;
  isStreaming: boolean;
  /** Present only when the run ended before this entry finished (a provider failure or a round with no stop), or on a resume's replay of an entry still streaming. */
  truncated?: true;
  /** Present only when a tool suppressed the response and the client was shown this entry blank or not at all. */
  suppressed?: true;
}

export interface ThinkingEntry {
  role: 'thinking';
  content: string;
  isStreaming: boolean;
  /** Present only when the run ended before this entry finished (a provider failure or a round with no stop), or on a resume's replay of an entry still streaming. */
  truncated?: true;
  /** Present only when a tool suppressed the response and the client was never sent this entry. */
  suppressed?: true;
}

export interface ToolEntry {
  role: 'tool';
  toolName: string;
  toolInput: Record<string, unknown>;
  timestamp: string;
}

export type SessionEntry = UserEntry | AssistantEntry | ThinkingEntry | ToolEntry;

export const ErrorCodes = {
  INVALID_MESSAGE: 'INVALID_MESSAGE',
  INVALID_FORMAT: 'INVALID_FORMAT',
  RATE_LIMITED: 'RATE_LIMITED',
  SERVER_ERROR: 'SERVER_ERROR',
} as const;

export interface ChatSession {
  sessionId: string;
  userId: string | number;
  entries: SessionEntry[];
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
  workspaceId?: string | number;
}

export interface AuthenticatedUser {
  id: string | number;
  [key: string]: unknown;
}
name: CI

on:
  pull_request:
  push:
    branches: [main]
  # Manual runs: re-checking a branch against a moved main, or confirming a gate after
  # changing one, without pushing an empty commit.
  workflow_dispatch:
  # An advisory published after a merge is invisible until someone opens a pull request, and this
  # repository can go days without one. Monday 07:00 UTC; only `build-chain` answers it.
  schedule:
    - cron: '0 7 * * 1'

# Every job here only reads the checkout; the repo default is write.
permissions:
  contents: read

# A newer push to the same branch supersedes an in-flight run. main is exempt:
# every commit there should have its own recorded result.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: ${{ github.ref != 'refs/heads/main' }}

jobs:
  verify:
    name: Verify
    # The scheduled run exists for the dependency audit; re-running the suite on an unchanged
    # tree every Monday would report nothing new.
    if: github.event_name != 'schedule'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
          # Full history, not for this job but for the spec anchor check below:
          # it resolves cited content from
          # origin/main, which a shallow clone cannot serve.
          fetch-depth: 0

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      # --ignore-scripts so `prepare` does not build on install: what a lifecycle script
      # runs is out of this workflow's control, and the Build step below is where a broken
      # compile should be reported. Type check catches it earlier still.
      - name: Install
        run: npm ci --ignore-scripts

      # Every `npm run` step below is one link of the `verify` script in
      # package.json, in the same order - scripts/verify-script.test.ts holds
      # the two together - and kept as separate steps so a red run names the
      # gate that failed rather than a single opaque command.
      - name: Type check
        run: npm run typecheck

      # example/ is outside tsconfig.json's rootDir, so nothing checked the one
      # file the README and the guide are written against.
      - name: Type check the example
        run: npm run typecheck:example

      - name: Lint (--max-warnings 0)
        run: npm run eslint

      # Reports, never blocks. The one rule it runs is `warn`, so the step exits
      # 0 on its own and carries no continue-on-error: a non-zero exit here now
      # means the config itself broke, and that should fail. Its findings render
      # as warning annotations rather than failures, which is what a report on a
      # passing check should look like.
      #
      # require-statement-links counts spec statements with no test behind them.
      # Most of what it reports needs a test written rather than a line changed,
      # so the count is meant to be visible on every run and to fall over time.
      # Its test-side mirror, require-spec-link, is satisfied and gates in the
      # Lint step above. Never add a rule here to escape a red gate -
      # eslint.config.backlog.mjs says what belongs.
      - name: Spec traceability backlog (report)
        run: npm run lint:backlog

      - name: Format check
        run: npm run prettier:check

      # Runs the whole suite and fails it on the committed coverage floor in
      # jest.config.js, so this is the test gate rather than an extra pass.
      - name: Test (with coverage floor)
        run: npm run test:coverage

      - name: Build
        run: npm run build

      # Anchors drift silently: a cited file gaining or losing lines above the
      # cited one leaves the link pointing at different content, and the spec
      # still reads as cited. Resolves content at origin/main, which the
      # fetch-depth: 0 above exists to provide. A red check is fixed by running
      # `node scripts/repoint-spec-anchors.mjs` and committing the result.
      - name: Spec anchor check
        run: node scripts/repoint-spec-anchors.mjs --check origin/main

      # A citation counts as coverage only in its statement's trailing
      # parenthetical; one written mid-statement is dropped by the Lore job in silence,
      # so the spec reads as cited while its coverage is zero. A red check is
      # fixed by moving the link to the end of its statement, never by deleting
      # it (AGENTS.md § Spec Test Links).
      # Every fenced typescript block in the three documented files is generated
      # from source; hand transcription is what produced the defects this catches.
      - name: Documented code blocks
        run: npm run docs:check

      # Three rules that held only because somebody remembered them: a path in prose that resolves,
      # a spike that says it is a spike, and an example region inside the EU.
      - name: Documented paths resolve
        run: npm run docs:check-paths

      - name: Spike documents carry a status block
        run: npm run docs:check-spikes

      - name: Documented regions
        run: npm run check:regions

      # A line number is a derived pointer; the name is what the author cited. This catches a citation
      # whose line moved under it, which no baseline comparison can see on a branch that edits the spec.
      - name: Spec citations name their test
        run: npm run spec:names

      - name: Spec link placement
        run: npm run check:spec-links

      # Lead paragraphs and a spec's status-vs-coverage are ESLint's job; the
      # one verdict a `files` glob cannot express - that an ADR's frontmatter
      # status parses, without holding the ADR to the coverage tier - is this
      # script's. `check:spec-status -- --coverage` lists unlinked statements
      # and never gates.
      - name: Spec status
        run: npm run check:spec-status

      # A release note and a commit subject have different readers, so this is a
      # file the author writes rather than something derived from the log. The
      # label is the escape hatch for a src/ change nothing installable observes.
      - name: Changelog entry
        if: github.event_name == 'pull_request' && !contains(github.event.pull_request.labels.*.name, 'no-changelog')
        # No fetch: the checkout above resolves every head into refs/remotes
        # with fetch-depth 0, and its credential is gone by the time a step
        # runs, so fetching here asked an unauthenticated git for a private
        # repository and exited 128 before the gate was ever reached.
        run: bash scripts/check-changelog.sh "origin/${{ github.base_ref }}"

  # Separate job, not a step on `verify`: these two check what the build chain
  # pulls in rather than what the code does, and a red audit should not read as
  # a failing test suite. It needs the tree installed but nothing built, so it
  # skips `prepare` with --ignore-scripts.
  build-chain:
    name: Build chain
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      - name: Install (no build)
        run: npm ci --ignore-scripts

      # Full tree, dev included: those packages are what a runner installs
      # before building dist/, and the release workflow signs what it produces.
      - name: Audit (high and above)
        run: npm run check:audit

      # A tag is a mutable pointer its owner can repoint under a job that holds
      # repository credentials.
      - name: Action pins
        run: npm run check:action-pins

  # Its own job because it is the only check that exercises the package as a
  # consumer receives it - packed, installed outside this tree, with no optional
  # peer present. Everything else here tests the source in place, where every
  # dependency is already installed and every one of these failures is invisible.
  smoke:
    name: Smoke (packed tarball)
    if: github.event_name != 'schedule'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      - name: Install (no build)
        run: npm ci --ignore-scripts

      # Explicit, rather than relying on `npm pack` to trigger `prepare`: a build failure should be
      # reported by a step named Build, not as a confusing pack error inside the smoke script.
      - name: Build
        run: npm run build

      # Two variants, two jobs' worth of signal in one: `bare` is a mock-provider consumer with no
      # optional peer, `full` is a Bedrock or Vertex consumer with both. They fail differently and
      # separate steps name which consumer is broken.
      - name: Smoke (no optional peer)
        run: npm run smoke -- bare

      - name: Smoke (both optional peers)
        run: npm run smoke -- full

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
}

/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
export function announcedId(client: WebSocket): () => string {
  let sessionId = '';
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
  });
  return () => sessionId;
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
